package com.calmcoloring.app.content.generated

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.graphics.Path

/**
 * Hand-authored Compose [Path] data for the "Sunny Day" template
 * (`svg/sunny-day.svg`, mockup id `sun`), one property per fillable region.
 *
 * NOTE ON MECHANISM: the plan's Step 2 asks for these to be generated by the
 * `br.com.devsrsouza.svg-to-compose` Gradle plugin. That plugin id/version
 * is not published to the Gradle Plugin Portal or Maven Central (verified:
 * both return "not found"), and a plugin-marker lookup on JitPack — its
 * only actual host — also 404s; only the raw, non-plugin-marker artifact
 * exists there, requiring a legacy `buildscript { classpath(...) }` +
 * `apply(plugin = ...)` wiring from a third-party repo not in this
 * project's allowlist. Its last release (0.11.0, ~2021) also predates
 * Compose Multiplatform's KMP restructure by years — a real incompatibility
 * with this project's pinned Kotlin 2.2.0 / Compose Multiplatform 1.10.3,
 * not a first-error bail. Per the task's pre-authorized fallback, these
 * Path objects are hand-translated from the SVG sources under `svg/` instead, preserving the
 * same per-template/per-region accessor shape the plan's TemplateCatalog
 * expects (plan: `CalmTemplateAssets.<Name>.<regionId>`; here:
 * `<TemplateName>Paths.<regionId>`).
 */
object SunnyDayPaths {
    val background: Path = backgroundPath()

    // d="M0,320 L0,235 Q160,175 320,235 L320,320 Z"
    val hill: Path = Path().apply {
        moveTo(0f, 320f)
        lineTo(0f, 235f)
        quadraticTo(160f, 175f, 320f, 235f)
        lineTo(320f, 320f)
        close()
    }

    // d="M55,150 a30,30 0 0 1 58,-10 a26,26 0 0 1 44,8 a24,24 0 0 1 -6,46 h-80 a26,26 0 0 1 -16,-44 Z"
    val cloud: Path = Path().apply {
        var x = 55f
        var y = 150f
        moveTo(x, y)
        svgArcTo(x, y, rx = 30f, ry = 30f, largeArc = false, sweep = true, x2 = x + 58f, y2 = y - 10f)
        x += 58f; y -= 10f
        svgArcTo(x, y, rx = 26f, ry = 26f, largeArc = false, sweep = true, x2 = x + 44f, y2 = y + 8f)
        x += 44f; y += 8f
        svgArcTo(x, y, rx = 24f, ry = 24f, largeArc = false, sweep = true, x2 = x - 6f, y2 = y + 46f)
        x -= 6f; y += 46f
        lineTo(x - 80f, y)
        x -= 80f
        svgArcTo(x, y, rx = 26f, ry = 26f, largeArc = false, sweep = true, x2 = x - 16f, y2 = y - 44f)
        close()
    }

    // cx=228 cy=92 r=48
    val sun: Path = Path().apply { addOval(Rect(center = Offset(228f, 92f), radius = 48f)) }
}
